namespace internal {
inline void prettify_element(simdjson::dom::element value, std::string &sb, size_t depth) {
  switch (value.type()) {
  case simdjson::dom::element_type::ARRAY: {
    simdjson::dom::array arr = value;
    sb.push_back('[');
    bool first = true;
    for (simdjson::dom::element child : arr) {
      if (!first) { sb.push_back(','); }
      first = false;
      sb.push_back('\n');
      sb.append(4 * (depth + 1), ' ');
      prettify_element(child, sb, depth + 1);
    }
    if (!first) { sb.push_back('\n'); sb.append(4 * depth, ' '); }
    sb.push_back(']');
    break;
  }
  case simdjson::dom::element_type::OBJECT: {
    simdjson::dom::object obj = value;
    sb.push_back('{');
    bool first = true;
    for (simdjson::dom::key_value_pair kv : obj) {
      if (!first) { sb.push_back(','); }
      first = false;
      sb.push_back('\n');
