    if (!first) { sb.push_back('\n'); sb.append(4 * depth, ' '); }
    sb.push_back('}');
    break;
  }
  default: {
    simdjson::internal::string_builder<> mb;
    mb.append(value);
    sb += mb.str();
  }
  }
}
} // internal
